css:
.cat-table{width:100%;border-collapse:collapse;font:400 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi)}
.cat-table th{text-align:left;padding:8px 12px;font:500 var(--cat-font-size-xs) var(--cat-font-family-ui);letter-spacing:.04em;text-transform:uppercase;color:var(--cat-color-ink-low);border-bottom:1px solid var(--cat-color-stroke-dark)}
.cat-table td{padding:9px 12px;border-bottom:1px solid var(--cat-color-stroke-softer)}
.cat-table tbody tr{transition:background 100ms ease-out}
.cat-table tbody tr:hover{background:var(--cat-color-surface-hover)}
.cat-table tbody tr.is-selected{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff}
.cat-table tbody tr.is-selected td{border-bottom-color:transparent}
